mapper.select:
/* sampleboard-mapper.xml id="selectSampleBoardList" 샘플게시판 목록 조회 */ SELECT seq , mb_id , title , content , writer_nm , DATE_FORMAT(in_dtm, '%Y-%m-%d %H:%i:%s') AS in_dtm , DATE_FORMAT(up_dtm, '%Y-%m-%d %H:%i:%s') AS up_dtm FROM tbts_sample_board WHERE mb_id = #{mb_id} AND use_yn = 'Y'
AND ( title LIKE CONCAT('%', #{search_word}, '%') OR content LIKE CONCAT('%', #{search_word}, '%') OR writer_nm LIKE CONCAT('%', #{search_word}, '%'))
ORDER BY seq DESC

mapper.insert:
/* sampleboard-mapper.xml id="insertSampleBoard" 샘플게시판 등록 */
INSERT
  INTO tbts_sample_board
     ( mb_id
     , title
     , content
     , writer_nm
     , use_yn
     , in_emp_cd
     , in_dtm
     )
VALUES
     ( #{mb_id}
     , #{title}
     , #{content}
     , #{writer_nm}
     , 'Y'
     , #{in_emp_cd}
     , NOW()
     )

mapper.update:
/* sampleboard-mapper.xml id="updateSampleBoard" 샘플게시판 수정 */
UPDATE tbts_sample_board
   SET title     = #{title}
     , content   = #{content}
     , writer_nm = #{writer_nm}
     , up_emp_cd = #{up_emp_cd}
     , up_dtm    = NOW()
 WHERE mb_id = #{mb_id}
   AND seq   = #{seq}

/* sampleboard-mapper.xml id="deleteSampleBoard" 샘플게시판 삭제(use_yn='N') */
UPDATE tbts_sample_board
   SET use_yn    = 'N'
     , up_emp_cd = #{up_emp_cd}
     , up_dtm    = NOW()
 WHERE mb_id = #{mb_id}
   AND seq   = #{seq}
